#!/usr/bin/env bash
# Documentation : « Contenu éditorial » en sept chapitres (remplace « Le constructeur de pages »),
# extraits et plages de lignes recalés sur le code modifié. Prérequis : apply-fix-contenu.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-contenu.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/contenu/un-contenu-fait-de-blocs.mdx" 2>/dev/null | grep -qF "Un contenu fait de blocs"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "richTextContentSchema" "packages/contracts/src/page/blocks.v1.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-contenu.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "apps/web/content/docs/dev/domaine/les-conventions.mdx" "apps/web/content/docs/dev/donnees/ecrire-et-faire-evoluer.mdx" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" "apps/web/content/docs/dev/stockage/lire-l-arbre.mdx" "apps/web/content/docs/dev/stockage/servir-un-fichier.mdx")
EXPECT=("3554a51abb3a:apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "01a0adc10716:apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "c87f2b72d9da:apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "d61516d20b71:apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "22d36ee8debd:apps/web/content/docs/dev/api/valider-l-entree.mdx" "040e13dd5ba5:apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "d233f902d74b:apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "0c17bd405d64:apps/web/content/docs/dev/domaine/les-conventions.mdx" "093a178eda2d:apps/web/content/docs/dev/donnees/ecrire-et-faire-evoluer.mdx" "e7e1c9fdb545:apps/web/content/docs/dev/membres/documents-des-membres.mdx" "09a74d904394:apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" "3f0c093442a1:apps/web/content/docs/dev/stockage/lire-l-arbre.mdx" "27af5eb26407:apps/web/content/docs/dev/stockage/servir-un-fichier.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/contenu/le-recensement-des-fichiers.mdx" "apps/web/content/docs/dev/contenu/le-registre-et-l-editeur.mdx" "apps/web/content/docs/dev/contenu/le-rendu-serveur.mdx" "apps/web/content/docs/dev/contenu/le-texte-riche.mdx" "apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "apps/web/content/docs/dev/contenu/un-contenu-fait-de-blocs.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Un contenu fait de blocs" "apps/web/content/docs/dev/contenu/un-contenu-fait-de-blocs.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/contenu"
