# Ancien chapitre remplacé par les sept nouveaux.
OLDF=apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx
if git cat-file -e "HEAD:$OLDF" 2>/dev/null; then rm -f "$OLDF"; MODIFIED+=("$OLDF"); fi
# Table de l'index : ligne « Contenu éditorial », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Contenu éditorial\",\"En sept chapitres : un contenu fait de blocs (contrat Zod, union discriminée, enveloppe versionnée, lecture tolérante) ; le texte riche (ce que generateHTML recopie, la liste blanche, un seul rendu) ; le registre et l’éditeur ; le rendu serveur (une requête pour tous les fichiers, l’audience des URLs) ; le recensement des fichiers ; un contenu écrit par un membre (la présentation d’instructeur) ; les réglages du site.\",\"rédigée\"]"
s2, n = re.subn(r'\["Contenu éditorial","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
